import { build } from 'esbuild'
import { readdir, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

const root = new URL('../', import.meta.url)
const files = (await readdir(new URL('resources/editor/modules/builtin/', root)))
  .filter(file => file.endsWith('.json')).sort()

// Browser imports and both standalone runtimes are generated before dev/build.
await writeFile(new URL('app/lib/editor/core/timeline/builtin-modules.ts', root), [
  '// Generated by scripts/prepare-editor.mjs; do not edit by hand.',
  'import type { ModuleManifest } from "./types";',
  ...files.map((file, index) => `import module${index} from "@/resources/editor/modules/builtin/${file}";`),
  `export const builtinModules = new Map<string, ModuleManifest>([${files.map((_, index) => `module${index}`).join(', ')}].map(module => [module.id, module as ModuleManifest]));`,
  '',
].join('\n'))

const shared = {
  absWorkingDir: fileURLToPath(root),
  bundle: true,
  platform: 'browser',
  target: 'es2022',
  minify: true,
}
await Promise.all([
  // AudioWorklet needs a standalone URL, outside the page's React bundle.
  build({ ...shared, entryPoints: ['app/lib/editor/workers/denoise.worklet.ts'],
    outfile: 'public/editor-workers/denoise.js', format: 'esm',
    banner: { js: '// Adapted from Uncut, MIT. See licenses/uncut/LICENSE. Generated by scripts/prepare-editor.mjs.' } }),
  // Rust embeds the shared planner for its isolated Chromium export worker.
  build({ ...shared, entryPoints: ['app/lib/editor/export/runtime.ts'],
    outfile: 'resources/editor/export-runtime.js', format: 'iife', globalName: 'BiliupExport',
    legalComments: 'none' }),
])
